def transform(grid):
    out = grid.copy()
    h, w = out.shape

    centers = {}
    for r in range(h):
        row_centers = []
        c = 0
        while c < w:
            if grid[r, c] == 7:
                s = c
                while c < w and grid[r, c] == 7:
                    c += 1
                e = c - 1
                m = (s + e) // 2
                row_centers.append(m)
                for cc in range(s, e + 1):
                    out[r, cc] = 8
                for rr in (r - 1, r, r + 1):
                    if 0 <= rr < h:
                        out[rr, m] = 6
            else:
                c += 1
        if row_centers:
            centers[r] = row_centers

    out[out == 3] = 8

    def runs_in_row(r):
        runs = []
        c = 0
        while c < w:
            while c < w and grid[r, c] == 0:
                c += 1
            if c >= w:
                break
            s = c
            while c < w and grid[r, c] != 0:
                c += 1
            runs.append((s, c - 1))
        return runs

    def has_hole(r):
        return any(grid[r, c] == 0 for c in range(w))

    def mark_left(r):
        runs = runs_in_row(r)
        if not runs:
            return
        if has_hole(r):
            out[r, runs[0][0]] = 3
        else:
            k = 2 if grid[r, 0] == 3 else 1
            for c in range(runs[0][0], min(runs[0][0] + k, runs[0][1] + 1)):
                out[r, c] = 3

    def mark_right(r):
        runs = runs_in_row(r)
        if not runs:
            return
        if has_hole(r):
            for s, e in runs:
                out[r, e] = 3
        else:
            k = 2 if grid[r, w - 1] == 3 else 1
            s, e = runs[-1]
            for c in range(max(s, e - k + 1), e + 1):
                out[r, c] = 3

    def bottom_marks(r, above):
        runs = runs_in_row(r)
        for a in above:
            for s, e in runs:
                if s <= a <= e:
                    out[r, s] = 3
                    break
        if runs:
            out[r, runs[-1][1]] = 3

    for r in range(0, h, 2):
        above = sorted(centers.get(r - 1, []))
        below = sorted(centers.get(r + 1, []))

        if above and not below:
            bottom_marks(r, above)
        elif not above and below:
            continue
        elif len(above) == len(below):
            diffs = [b - a for a, b in zip(above, below)]
            if diffs and all(d > 0 for d in diffs):
                mark_left(r)
            elif diffs and all(d < 0 for d in diffs):
                mark_right(r)
        elif len(above) > len(below) and below:
            if min(below) > min(above):
                mark_left(r)
            if max(below) < max(above):
                mark_right(r)

    return out

