    out = grid.copy()
    h, w = out.shape

    # Turn each horizontal 777 bridge into an 8-6-8 gate, and extend the 6
    # vertically onto the neighboring horizontal rails.
    centers_by_gap = {}
    for r in range(h):
        c = 0
        while c <= w - 3:
