                mid = c + 1
                out[r, c:c + 3] = [8, 6, 8]
                if r - 1 >= 0:
                    out[r - 1, mid] = 6
                if r + 1 < h:
                    out[r + 1, mid] = 6
                centers_by_gap[r] = centers_by_gap.get(r, []) + [mid]
                c += 3
            else:
                c += 1

    # Remove original rail-end markers.
    out[grid == 3] = 8

    # Restore blue markers on horizontal rails according to connectivity from
    # the left and right edges through the inserted gates.
    rail_rows = [r for r in range(h) if r % 2 == 0]
    left = True
    right = True

    for i, r in enumerate(rail_rows):
        above = r - 1
        if above in centers_by_gap:
            cs = centers_by_gap[above]
            if any(c <= 4 for c in cs):
                left = not left
            if any(c >= w - 5 for c in cs):
