        if right and r != 0:
            out[r, w - 1] = 3
            if below in centers_by_gap and any(c >= w - 5 for c in centers_by_gap[below]):
                out[r, w - 2] = 3

    return out

def transform(grid):
    h, w = grid.shape
    vals, counts = np.unique(grid, return_counts=True)
    bg = vals[np.argmax(counts)]
    fg_vals = vals[vals != bg]
    if len(fg_vals) == 0:
        return grid.copy()
    fg = fg_vals[0]

    mask = grid != bg
    seen = np.zeros((h, w), dtype=bool)
    comps = []

    for r in range(h):
        for c in range(w):
            if not mask[r, c] or seen[r, c]:
                continue
            stack = [(r, c)]
            seen[r, c] = True
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and mask[ny, nx] and not seen[ny, nx]:
                        seen[ny, nx] = True
                        stack.append((ny, nx))
            ys = [p[0] for p in cells]
            xs = [p[1] for p in cells]
            comps.append({
                "bbox": (min(ys), min(xs), max(ys), max(xs)),
                "children": [],
                "area": len(cells),
            })

    n = len(comps)
    parent = [-1] * n

    for i in range(n):
        y1, x1, y2, x2 = comps[i]["bbox"]
        best = -1
        best_area = None
        for j in range(n):
            if i == j:
                continue
            a1, b1, a2, b2 = comps[j]["bbox"]
            if a1 < y1 and b1 < x1 and a2 > y2 and b2 > x2:
                area = (a2 - a1 + 1) * (b2 - b1 + 1)
                if best_area is None or area < best_area:
                    best = j
                    best_area = area
        parent[i] = best

    for i, p in enumerate(parent):
        if p != -1:
            comps[p]["children"].append(i)

    def overlap(a, b):
        return max(a[0], b[0]) <= min(a[1], b[1])

    def axis_positions(items, sizes, axis):
        intervals = []
        for idx in items:
            y1, x1, y2, x2 = comps[idx]["bbox"]
            intervals.append((y1, y2) if axis == 0 else (x1, x2))

        order = sorted(range(len(items)), key=lambda k: (intervals[k][0] + intervals[k][1]) / 2)
        groups = []
        for k in order:
            iv = intervals[k]
            placed = False
            for g in groups:
                if overlap(iv, g["span"]):
                    g["members"].append(k)
                    g["span"] = (min(g["span"][0], iv[0]), max(g["span"][1], iv[1]))
                    placed = True
                    break
            if not placed:
                groups.append({"span": iv, "members": [k]})

        groups.sort(key=lambda g: (g["span"][0] + g["span"][1]) / 2)
        pos = [0] * len(items)
        cur = 0
        for g in groups:
            extent = max(sizes[k] for k in g["members"])
            for k in g["members"]:
                pos[k] = cur + (extent - sizes[k]) // 2
            cur += extent + 1
        return pos, max(0, cur - 1)

    def render(idx):
        kids = comps[idx]["children"]
        if not kids:
            return np.array([[fg]], dtype=grid.dtype)

        child_imgs = [render(k) for k in kids]
        child_h = [im.shape[0] for im in child_imgs]
        child_w = [im.shape[1] for im in child_imgs]

        ys, inner_h = axis_positions(kids, child_h, 0)
        xs, inner_w = axis_positions(kids, child_w, 1)

        out = np.full((inner_h + 4, inner_w + 4), bg, dtype=grid.dtype)
        out[0, :] = fg
        out[-1, :] = fg
        out[:, 0] = fg
        out[:, -1] = fg

        for im, y, x in zip(child_imgs, ys, xs):
            out[y + 2:y + 2 + im.shape[0], x + 2:x + 2 + im.shape[1]] = im
        return out

    roots = [i for i, p in enumerate(parent) if p == -1]
    if len(roots) == 1:
        return render(roots[0])

    root_imgs = [render(i) for i in roots]
    roots = sorted(roots, key=lambda i: comps[i]["bbox"][1])
    root_imgs = [render(i) for i in roots]

    total_h = max(im.shape[0] for im in root_imgs)
    min_y = min(comps[i]["bbox"][0] for i in roots)
    max_y = max(comps[i]["bbox"][2] for i in roots)
    span_y = max(1, max_y - min_y)

    xs = []
    cur = 0
    for im in root_imgs:
        xs.append(cur)
        cur += im.shape[1] + 1

    out = np.full((total_h, cur), bg, dtype=grid.dtype)
    for idx, im, x in zip(roots, root_imgs, xs):
        y1, _, y2, _ = comps[idx]["bbox"]
        cy = (y1 + y2) / 2
        y = int(round((cy - min_y) / span_y * (total_h - 1) - (im.shape[0] - 1) / 2))
        y = max(0, min(total_h - im.shape[0], y))
        out[y:y + im.shape[0], x:x + im.shape[1]] = im

    return out

def transform(grid):
    h, w = grid.shape

    vals, counts = np.unique(grid, return_counts=True)
    bg = vals[np.argmax(counts)]
    other = vals[vals != bg]
