    for r, c in pts:
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            q = (r + dr, c + dc)
            if q in S:
                adj[(r, c)].append(q)

    idx, low, stack, comps = {}, {}, [], []
    t = [0]

    def dfs(u, parent):
        t[0] += 1
        idx[u] = low[u] = t[0]
        for v in adj[u]:
            e = (u, v) if u < v else (v, u)
            if v == parent:
