            if v not in idx:
                stack.append(e)
                dfs(v, u)
                low[u] = min(low[u], low[v])
                if low[v] >= idx[u]:
                    comp = []
                    while stack:
                        ee = stack.pop()
                        comp.append(ee)
                        if ee == e:
                            break
                    comps.append(comp)
            elif idx[v] < idx[u]:
                stack.append(e)
                low[u] = min(low[u], idx[v])

    for p in pts:
        if p not in idx:
            dfs(p, None)

    nodes = []
    for comp in comps:
        vs = set()
        for a, b in comp:
            vs.add(a)
            vs.add(b)
        if len(comp) >= len(vs):
            rs = [p[0] for p in vs]
            cs = [p[1] for p in vs]
