                    y = 0
                if y + a.shape[0] > height:
                    y = height - a.shape[0]
                out[y:y + a.shape[0], x:x + a.shape[1]] = a
                anchors.append((y + an[0], x + an[1]))
                x += a.shape[1] + 1
            return out, anchors[0]
        else:
            height = sum(a.shape[0] for a, an in rendered) + len(rendered) - 1
            if trailing:
                height += 1
            width = max(a.shape[1] for a, an in rendered)
            anchor_col = rendered[0][1][1]
            out = np.full((height, width), bg, dtype=grid.dtype)
            y = 0
            anchors = []
            for a, an in rendered:
                x = anchor_col - an[1]
                if x < 0:
                    x = 0
                if x + a.shape[1] > width:
                    x = width - a.shape[1]
                out[y:y + a.shape[0], x:x + a.shape[1]] = a
                anchors.append((y + an[0], x + an[1]))
                y += a.shape[0] + 1
