        if not n["children"]:
            a = np.full((1, 1), fg, dtype=grid.dtype)
            return a, (0, 0)

        ch = sorted(n["children"], key=lambda x: (center(x)[0], center(x)[1]))
        rs = [center(x)[0] for x in ch]
        cs = [center(x)[1] for x in ch]
        horizontal = (max(cs) - min(cs)) >= (max(rs) - min(rs))
        if horizontal:
            ch = sorted(ch, key=lambda x: center(x)[1])
        else:
            ch = sorted(ch, key=lambda x: center(x)[0])

        inner, anch = compose(ch, horizontal)
        out = np.full((inner.shape[0] + 4, inner.shape[1] + 4), bg, dtype=grid.dtype)
        out[0, :] = fg
        out[-1, :] = fg
        out[:, 0] = fg
        out[:, -1] = fg
        out[2:2 + inner.shape[0], 2:2 + inner.shape[1]] = inner
        return out, (anch[0] + 2, anch[1] + 2)

