        return grid.copy()

    if len(roots) == 1:
        return render(roots[0])[0]

    rs = [center(x)[0] for x in roots]
    cs = [center(x)[1] for x in roots]
    horizontal = (max(cs) - min(cs)) >= (max(rs) - min(rs))
    roots = sorted(roots, key=lambda x: center(x)[1] if horizontal else center(x)[0])
    return compose(roots, horizontal, trailing=True)[0]

