            for i, p in enumerate(pieces):
                if used[i]:
                    continue

                ph, pw = p.shape
                top, bottom, left, right = edges[i]

                for rr in range(max(0, r - ph + 1), min(r, H - ph) + 1):
                    for cc in range(max(0, c - pw + 1), min(c, W - pw) + 1):
