            for i, rr, cc in choices:
                p = pieces[i]
                ph, pw = p.shape
                used[i] = True
                occ[rr:rr + ph, cc:cc + pw] = True
                out[rr:rr + ph, cc:cc + pw] = p

                if backtrack(n + 1):
                    return True

                out[rr:rr + ph, cc:cc + pw] = -1
                occ[rr:rr + ph, cc:cc + pw] = False
