            for c in range(w0):
                if seen2[r, c] or not rare_mask[r, c]:
                    continue

                q = [(r, c)]
                seen2[r, c] = True
                cells = []

                for x, y in q:
                    cells.append((x, y))
                    for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        nx, ny = x + dx, y + dy
                        if (
                            0 <= nx < h0
                            and 0 <= ny < w0
                            and not seen2[nx, ny]
                            and rare_mask[nx, ny]
